	"location_id" uuid,
	"business_date" date NOT NULL,
	"metric_id" text NOT NULL,
	"dimension_key" text DEFAULT '' NOT NULL,
	"dimension_value" text DEFAULT '' NOT NULL,
	"unit" text NOT NULL,
