	"definition_version" integer NOT NULL,
	"computed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"job_run_id" uuid,
	CONSTRAINT "iq_daily_facts_key_unique" UNIQUE NULLS NOT DISTINCT("org_id","location_id","business_date","metric_id","dimension_key","dimension_value","definition_version"),
	CONSTRAINT "iq_daily_facts_metric_id_check" CHECK ("iq_daily_facts"."metric_id" ~ '^[a-z][a-z0-9_]{0,63}$'),
	CONSTRAINT "iq_daily_facts_dimension_check" CHECK (("iq_daily_facts"."dimension_key" = '' AND "iq_daily_facts"."dimension_value" = '')
        OR ("iq_daily_facts"."dimension_key" ~ '^[a-z][a-z0-9_]{0,63}$' AND char_length("iq_daily_facts"."dimension_value") BETWEEN 1 AND 200)),
	CONSTRAINT "iq_daily_facts_unit_check" CHECK ("iq_daily_facts"."unit" IN ('paise', 'count')),
	CONSTRAINT "iq_daily_facts_source_row_count_check" CHECK ("iq_daily_facts"."source_row_count" >= 0),
