-- RLS and grants. Supabase's defaults still give anon/authenticated SELECT,
-- REFERENCES and TRIGGER on new tables (0033 revoked only writes), so each
-- table starts from REVOKE ALL. Reading through a Supabase key is limited to
-- OWNER and MANAGER of the row's org — the finance.view roles in
-- src/domain/permissions.ts — because these rows are revenue, food cost and
-- expense figures. The app reads and writes as postgres, which bypasses RLS,
-- and its repositories filter on org_id themselves.
DO $$
DECLARE
  target text;
BEGIN
  FOREACH target IN ARRAY ARRAY['iq_daily_facts', 'iq_intraday_facts', 'iq_daily_trust'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', target);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', target);
    EXECUTE format('REVOKE ALL ON TABLE %I FROM PUBLIC, anon, authenticated', target);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR SELECT TO authenticated
         USING (auth_has_role(org_id, ARRAY[''OWNER'', ''MANAGER'']))',
      target || '_finance_read', target
    );
    EXECUTE format('GRANT SELECT ON TABLE %I TO authenticated', target);
  END LOOP;
END $$;
